import json
d=json.load(open('/tmp/rm3.json'))
items=d['items'] if isinstance(d,dict) and 'items' in d else d
live={'review-ajc','review-ajcr','ajc-p1','ajc-p2','ajc-p3','ajc-p4','ajcr-p1','ajcr-p2','ajcr-p3','ajcr-p4'}
byid={it['id']:it for it in items}
act=[it for it in items if it.get('status')=='active']
print('ACTIVE NOW:',len(act))
# an active row is legitimate if owned by live lane OR is ancestor of such a row
legit=set()
for it in items:
    if (it.get('owner') or '') in live:
        legit.add(it['id'])
        p=it.get('parent')
        while p and p in byid:
            legit.add(p); p=byid[p].get('parent')
print()
print('ACTIVE + LIVE-BACKED (spine):')
for it in act:
    if it['id'] in legit: print('  ',it['id'],'owner=',it.get('owner') or '(spine)')
print()
print('ACTIVE with NO live owner and NOT a live spine -> candidates for pending:')
for it in act:
    if it['id'] not in legit: print('  ',it['id'],'owner=',it.get('owner') or '-')
"

